# Название в первом столбце должно быть коротким законом. Полная причинная
# расшифровка остаётся во втором столбце, поэтому хвост после «;» не дублируем.
deep_programs = {key: value.split(";", 1)[0].strip() for key, value in deep_programs.items()}

program_count = sum(len(rows) for _, _, rows in stages)
assert len(deep_programs) == program_count, (len(deep_programs), program_count)
stages = [
    (kicker, title, [(deep_programs[program], mechanism, questions, anchor)
                     for program, mechanism, questions, anchor in rows])
    for kicker, title, rows in stages
]


def shade(cell, fill):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = tcPr.find(qn("w:shd"))
    if shd is None:
        shd = OxmlElement("w:shd")
        tcPr.append(shd)
    shd.set(qn("w:fill"), fill)


def set_cell_margins(cell, top=90, start=100, bottom=90, end=100):
    tc = cell._tc
    tcPr = tc.get_or_add_tcPr()
    tcMar = tcPr.first_child_found_in("w:tcMar")
    if tcMar is None:
        tcMar = OxmlElement("w:tcMar")
        tcPr.append(tcMar)
    for m, v in (("top", top), ("start", start), ("bottom", bottom), ("end", end)):
        node = tcMar.find(qn(f"w:{m}"))
        if node is None:
            node = OxmlElement(f"w:{m}")
            tcMar.append(node)
        node.set(qn("w:w"), str(v))
        node.set(qn("w:type"), "dxa")


def set_repeat_table_header(row):
    trPr = row._tr.get_or_add_trPr()
    tblHeader = OxmlElement("w:tblHeader")
    tblHeader.set(qn("w:val"), "true")
    trPr.append(tblHeader)


def set_repeat_as_header(paragraph):
    paragraph.paragraph_format.keep_with_next = True


def font_run(run, size=9, bold=False, color="20242A", name="Arial"):
    run.font.name = name
    run._element.get_or_add_rPr().rFonts.set(qn("w:ascii"), name)
    run._element.get_or_add_rPr().rFonts.set(qn("w:hAnsi"), name)
    run._element.get_or_add_rPr().rFonts.set(qn("w:eastAsia"), name)
    run.font.size = Pt(size)
    run.bold = bold
    run.font.color.rgb = RGBColor.from_string(color)


def add_cell_text(cell, text, bold_first=False, size=8.5):
    cell.text = ""
    p = cell.paragraphs[0]
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(0)
    p.paragraph_format.line_spacing = 1.05
    if bold_first and ":" in text:
        first, rest = text.split(":", 1)
        r = p.add_run(first + ":")
        font_run(r, size=size, bold=True)
        r = p.add_run(rest)
        font_run(r, size=size)
    else:
        r = p.add_run(text)
        font_run(r, size=size, bold=bold_first)


